import { getDaysInMonth, isValid } from 'date-fns';
import { isNil } from 'lodash-es';
import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useIntl } from 'react-intl';

import { useDateTimeFormat } from './useDateTimeFormat.js';
import { _SpinButtonGroup as SpinButtonGroup } from '../../spin-buttons/spin-button-group/SpinButtonGroup.js';
import type { SpinButtonHandler } from '../../spin-buttons/spin-button-group/types.js';
import type { DateTimePickerProps } from '../types.js';

/**
 * Returns a list of preconfigured spinbuttons for a given datetime and format configuration.
 */
export function useSpinButtons(
  isoDateTime: string | null,
  type: DateTimePickerProps['type'],
  precision: DateTimePickerProps['precision'],
  isDisabled: boolean,
  isReadonly: boolean,
) {
  const intl = useIntl();

  const { toParts, toDateTime, emptyParts } = useDateTimeFormat(
    type,
    precision,
  );
  const [parts, setParts] = useState(
    isoDateTime === null ? emptyParts : toParts(new Date(isoDateTime)),
  );
  const hasDayPeriod = useMemo(
    () => parts.some((p) => p.type === 'dayPeriod'),
    [parts],
  );

  const dateTime = useMemo(() => toDateTime(parts), [parts, toDateTime]);
  const daysInMonth =
    dateTime !== null && isValid(dateTime) ? getDaysInMonth(dateTime) : 31;

  const updatePart = useCallback(
    (type: Intl.DateTimeFormatPart['type'], value: string) => {
      setParts((prevParts) => {
        const index = prevParts.findIndex((p) => p.type === type);

        // Ignore invalid part type or if value is unchanged
        if (index < 0 || prevParts[index].value === value) {
          return prevParts;
        }

        // Clone the parts and update entry with new value
        const newParts = [...prevParts];
        newParts[index] = { type, value };
        return newParts;
      });
    },
    [],
  );

  const { spinButtons, handlers } = useMemo(() => {
    // Keep a map of all the imperative handlers per spinbutton
    const handlers = new Map<Intl.DateTimeFormatPartTypes, SpinButtonHandler>();

    // Create an array of preconfigured spinbuttons for each datetime part.
    const spinButtons = parts.map(({ type, value }, index) => {
      // Set of props all spinbuttons have in common.
      const commonProps = {
        key: type,
        ref: (handler: SpinButtonHandler | null) =>
          handler && handlers.set(type, handler),
        defaultValue: value === '' ? null : parseInt(value),
        onChange: (value: string | number | null) => {
          if (value === null) {
            updatePart(type, '');
            return;
          }

          // ignore 0 value for day/month/year during input (e.g. prefix with 0)
          if (
            (type === 'day' || type === 'month' || type === 'year') &&
            value === 0
          ) {
            //ignore to preserve 0 if entered as prefix
            return;
          }

          // ignore 0 value for hour in 12h format during input (e.g. prefix with 0)
          if (type === 'hour' && hasDayPeriod && value === 0) {
            //ignore to preserve 0 if entered as prefix
            return;
          }

          updatePart(
            type,
            typeof value === 'number' ? value.toString() : value,
          );
        },
        disabled: isDisabled,
        readonly: isReadonly,
      };

      switch (type) {
        case 'year':
          return (
            <SpinButtonGroup.Number
              {...commonProps}
              minValue={0}
              maxValue={9999}
              displayFormat={{ length: 4 }}
              placeholder={intl.formatMessage({
                defaultMessage: 'yyyy',
                id: 'c6bnAmHe/EY7/jQS',
                description: 'The abbreviation of the year part of a date',
              })}
            />
          );
        case 'month':
          return (
            <SpinButtonGroup.Number
              {...commonProps}
              minValue={1}
              maxValue={12}
              displayFormat={{ length: 2 }}
              placeholder={intl.formatMessage({
                defaultMessage: 'mm',
                id: 'LnDfRkxwzq9Vq/up',
                description: 'The abbreviation of the month part of a date',
              })}
            />
          );
        case 'day':
          return (
            <SpinButtonGroup.Number
              {...commonProps}
              minValue={1}
              maxValue={daysInMonth}
              displayFormat={{ length: 2 }}
              placeholder={intl.formatMessage({
                defaultMessage: 'dd',
                id: 'akyhaFko0pgLR1Q5',
                description: 'The abbreviation of the day part of a date',
              })}
            />
          );
        case 'hour':
          return (
            <SpinButtonGroup.Number
              {...commonProps}
              minValue={hasDayPeriod ? 1 : 0}
              maxValue={hasDayPeriod ? 12 : 23}
              displayFormat={{ length: 2 }}
              placeholder={intl.formatMessage({
                defaultMessage: 'hh',
                id: '8ioXZP1LdljRBssM',
                description: 'The abbreviation of the hour part of a time',
              })}
            />
          );
        case 'minute':
          return (
            <SpinButtonGroup.Number
              {...commonProps}
              minValue={0}
              maxValue={59}
              displayFormat={{ length: 2 }}
              placeholder={intl.formatMessage({
                defaultMessage: 'mm',
                id: 'Uk/Q/HKAITavgOfU',
                description: 'The abbreviation of the minute part of a time',
              })}
            />
          );
        case 'second':
          return (
            <SpinButtonGroup.Number
              {...commonProps}
              minValue={0}
              maxValue={59}
              displayFormat={{ length: 2 }}
              placeholder={intl.formatMessage({
                defaultMessage: 'ss',
                id: 'wnjOChhd1Lw9s9Gg',
                description: 'The abbreviation of the second part of a time',
              })}
            />
          );
        case 'fractionalSecond':
          return (
            <SpinButtonGroup.Number
              {...commonProps}
              minValue={0}
              maxValue={999}
              displayFormat={{ length: 3 }}
              placeholder={intl.formatMessage({
                defaultMessage: 'fff',
                id: 'ZSJMoZevK9FVBtMR',
                description:
                  'The abbreviation of the fractional of a second part of a time',
              })}
            />
          );
        case 'dayPeriod':
          return (
            <SpinButtonGroup.Text
              {...commonProps}
              defaultValue={value === '' ? null : value}
              values={['AM', 'PM']}
              placeholder={intl.formatMessage({
                defaultMessage: 'aa',
                id: 'IBvpLUGNaSb3Jsej',
                description:
                  'The abbreviation the day period (am/pm) part of a time',
              })}
            />
          );
        case 'literal':
          return isNil(value) ? null : (
            // Show the whole literal but only use the first char as trigger.
            <SpinButtonGroup.Separator
              key={`${type}_${index}`}
              trigger={value[0]}
            >
              {value}
            </SpinButtonGroup.Separator>
          );
        default:
          // For unknown part types, simply render the value as textnode in the DOM.
          return value;
      }
    });

    return { handlers, spinButtons };
    // Do not recreate the spinbuttons on parts update. This prevents prefix issues when starting values with 0.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isDisabled, isReadonly, updatePart, daysInMonth, hasDayPeriod]);

  // Callback to push the given part values to the corresponding spinbuttons.
  const updateParts = useCallback(
    (updatedParts: Intl.DateTimeFormatPart[]) => {
      const nonLiteralParts = updatedParts.filter(
        ({ type }) => type !== 'literal',
      );

      const lookup = new Map(
        nonLiteralParts.map(({ type, value }) => [type, value]),
      );

      // Apply the new values to the spinbuttons.
      // Would not be necessary, if the spinbuttons would be controlled. But this is not possible because this
      // interferes with the expected typing behavior for spinbuttons with format patterns like for this one used for the datetime parts.
      nonLiteralParts.forEach((part) => {
        const handler = handlers.get(part.type);
        if (part.value === '') {
          handler?.clearValue();
        } else if (handler?.type === 'number') {
          handler.applyText(part.value);
        } else if (handler?.type === 'text') {
          handler.searchValue(part.value[0]);
        }
      });

      // update the parts with new values
      setParts((prevParts) => {
        return prevParts.map((part) => {
          const newValue = lookup.get(part.type);
          return newValue !== undefined ? { ...part, value: newValue } : part;
        });
      });
    },
    [handlers],
  );

  // If the format, type or precision is changing, restore the prev. values when generating a set of new spinbuttons.
  useEffect(() => {
    setParts((parts) => {
      const newDateTime = toDateTime(parts);
      return newDateTime === null ? emptyParts : toParts(newDateTime);
    });
  }, [emptyParts, toDateTime, toParts]);

  return {
    spinButtons,
    dateTime,
    updateParts,
    handlers,
    parts,
  };
}
